// Node 1 of 3 — Normalize & validate.
//
// Accepts three shapes without caring which: a Meta Lead Ads webhook, a plain
// JSON website form, or a form-encoded POST. Emits one flat lead object.
//
// Rule that matters: a lead is only INVALID if we cannot reach the human.
// Everything else is a warning. A missing name is not a reason to drop someone
// who left a working phone number.

function normalizeLead(raw) {
  const flat = {};

  // Meta Lead Ads nests the answers in entry[].changes[].value.field_data[].
  const fd =
    raw?.entry?.[0]?.changes?.[0]?.value?.field_data ||
    raw?.field_data ||
    null;

  if (Array.isArray(fd)) {
    for (const f of fd) {
      const key = String(f?.name ?? '').toLowerCase().trim();
      if (!key) continue;
      flat[key] = Array.isArray(f?.values) ? f.values[0] : f?.value;
    }
  }

  // Plain form shapes: take every scalar at the top level.
  for (const [k, v] of Object.entries(raw ?? {})) {
    if (typeof v === 'string' || typeof v === 'number') {
      flat[k.toLowerCase().trim()] = v;
    }
  }

  const pick = (...names) => {
    for (const n of names) {
      const v = flat[n];
      if (v !== undefined && v !== null && String(v).trim() !== '') {
        return String(v).trim();
      }
    }
    return '';
  };

  const name = pick('full_name', 'fullname', 'name', 'contact_name', 'first_name');
  const emailRaw = pick('email', 'email_address', 'work_email').toLowerCase();
  const phoneRaw = pick('phone', 'phone_number', 'mobile', 'tel', 'telephone');
  const message = pick(
    'message', 'notes', 'comments', 'details', 'job_description',
    'describe_your_project', 'what_do_you_need', 'how_can_we_help'
  );
  const service = pick('service', 'service_needed', 'job_type', 'category', 'what_service');
  const city = pick('city', 'town', 'location');
  const zip = pick('zip', 'zip_code', 'postal_code', 'postcode');
  const source = pick('source', 'utm_source', 'platform') ||
    (Array.isArray(fd) ? 'meta_lead_ads' : 'web_form');

  // Phone → E.164. Twilio rejects anything else, so do it here, once.
  const digits = phoneRaw.replace(/[^\d]/g, '');
  let phone = '';
  if (digits.length === 10) phone = '+1' + digits;
  else if (digits.length === 11 && digits.startsWith('1')) phone = '+' + digits;
  else if (digits.length >= 11 && digits.length <= 15) phone = '+' + digits;

  // The domain is one or more dot-separated labels followed by a TLD. The first
  // version of this pattern forbade dots inside the domain, which silently
  // rejected every "@company.co.uk" and every subdomain address — and a lead who
  // left only that email was then marked unreachable and never contacted at all.
  // Deliberately not RFC 5322: the only question is whether it is worth sending
  // to, and anything this lets through that bounces will bounce visibly.
  const emailOk = /^[^@\s]+@([a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/i.test(emailRaw);
  const email = emailOk ? emailRaw : '';

  const errors = [];
  const warnings = [];

  // The ONLY fatal condition: nobody to contact.
  if (!phone && !email) {
    errors.push('unreachable: no usable phone and no usable email');
  }
  if (phoneRaw && !phone) warnings.push(`phone could not be parsed: "${phoneRaw}"`);
  if (emailRaw && !emailOk) warnings.push(`email could not be parsed: "${emailRaw}"`);
  if (!name) warnings.push('no name supplied');
  if (!message && !service) warnings.push('no message and no service selected');

  return {
    valid: errors.length === 0,
    errors,
    warnings,
    lead: {
      name,
      email,
      phone,
      message,
      service,
      city,
      zip,
      source,
      received_at: new Date().toISOString(),
      t0: Date.now(),
      // Used to suppress a duplicate alert if the same person submits twice.
      dedupe_key: (phone || email || name).toLowerCase(),
      raw_field_count: Object.keys(flat).length,
    },
  };
}

// ---- n8n glue ----
const out = [];
for (const item of $input.all()) {
  // Webhook v2 puts the posted body under .body; accept a bare object too.
  out.push({ json: normalizeLead(item.json.body ?? item.json) });
}
return out;

// Node 2 of 3 — Qualify.
//
// Takes whatever the model returned (or whatever the API error was) and always
// produces a usable qualification. The AI is allowed to fail; the lead is not
// allowed to disappear. If the model is down, rate-limited, or returns garbage,
// `ruleScore` answers instead and `source` says so out loud.
//
// Two deliberate choices:
//   1. The tier is ALWAYS recomputed from the score here. The model's own tier
//      field is ignored even when present — a score and a tier that agree today
//      are not a guarantee they agree tomorrow.
//   2. The model never computes a number we depend on for routing. It writes
//      the sentence a human reads; the score it proposes is clamped and bounded
//      by the rule engine.

const TIER_A_MIN = 70;
const TIER_B_MIN = 40;

function tierFor(score) {
  if (score >= TIER_A_MIN) return 'A';
  if (score >= TIER_B_MIN) return 'B';
  return 'C';
}

// Deterministic scorer. Runs on every lead, used alone when the AI is unusable,
// and used as a sanity bound when the AI is usable.
function ruleScore(lead) {
  const reasons = [];
  let s = 20;

  if (lead.phone) { s += 25; reasons.push('reachable by phone'); }
  if (lead.email) { s += 10; reasons.push('email present'); }
  if (lead.service) { s += 10; reasons.push('named a service'); }

  const msg = String(lead.message || '');
  const words = msg.split(/\s+/).filter(Boolean).length;
  if (words >= 15) { s += 15; reasons.push('detailed message'); }
  else if (words >= 5) { s += 8; reasons.push('some detail'); }

  const urgent = /\b(asap|today|tonight|tomorrow|urgent|emergency|right away|no heat|no hot water|no a\/?c|not working|stopped working|broken|leak|leaking|flood)/i;
  if (urgent.test(msg)) { s += 20; reasons.push('urgency language'); }

  const shopping = /\b(just looking|just curious|just browsing|how much (is|does|would)|ballpark|price range|price list|quote only|not ready|window shopping)\b/i;
  if (shopping.test(msg)) { s -= 15; reasons.push('price-shopping language'); }

  const spam = /\b(seo services|rank your (site|website)|increase your traffic|guest post|backlink|crypto|loan offer|bitcoin|investment opportunity)\b/i;
  const junkName = /^(test|asdf|qwerty|aaa+|xxx+|n\/?a)$/i;
  if (spam.test(msg) || junkName.test(String(lead.name || '').trim())) {
    s = Math.min(s, 10);
    reasons.push('matches spam/test pattern');
  }

  // Capped at 95, not 100. The weights above happen to sum to exactly 100 on a
  // good lead, and a rules-only score of "100" reads like certainty the rule
  // engine does not have — it has seen a phone number and some keywords. 95
  // leaves the top of the range for a qualification that actually read the text.
  s = Math.max(0, Math.min(95, Math.round(s)));
  return { score: s, tier: tierFor(s), reasons };
}

// Pull the first JSON object out of model output that may be fenced, prefixed,
// or (because we prefill the assistant turn with "{") missing its opening brace.
function extractJson(text) {
  if (typeof text !== 'string' || text.trim() === '') return null;
  let t = text.trim();
  t = t.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  if (!t.startsWith('{')) {
    const i = t.indexOf('{');
    if (i === -1) t = '{' + t;        // assistant prefill case
    else t = t.slice(i);
  }
  const end = t.lastIndexOf('}');
  if (end !== -1) t = t.slice(0, end + 1);
  try { return JSON.parse(t); } catch { return null; }
}

function clip(text, max) {
  const s = String(text ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const cut = s.slice(0, max - 1);
  const sp = cut.lastIndexOf(' ');
  return (sp > max * 0.6 ? cut.slice(0, sp) : cut).trim() + '\u2026';
}

// `aiText` is the model's text, or '' / null when the API call failed.
function qualify(lead, aiText, apiError) {
  const fb = ruleScore(lead);
  const parsed = extractJson(aiText);

  const problems = [];
  if (apiError) problems.push(`api: ${String(apiError).slice(0, 120)}`);
  if (!parsed) problems.push(aiText ? 'model output was not valid JSON' : 'no model output');

  let score = fb.score;
  let summary = '';
  let intent = '';
  let urgency = '';
  let next_question = '';
  let red_flags = [];
  let source = 'fallback';

  if (parsed) {
    const n = Number(parsed.score);
    const hasScore = Number.isFinite(n);
    if (!hasScore) problems.push('model score missing or not a number');

    summary = clip(parsed.summary_for_owner ?? parsed.summary, 200);
    intent = clip(parsed.intent, 60);
    urgency = clip(parsed.urgency, 24);
    next_question = clip(parsed.first_question ?? parsed.suggested_first_question, 120);
    red_flags = Array.isArray(parsed.red_flags)
      ? parsed.red_flags.map((r) => clip(r, 60)).filter(Boolean).slice(0, 4)
      : [];

    if (!summary) problems.push('model summary was empty');

    // Accept the model's score only if it is a real number AND within 25 points
    // of the rule engine. A wild disagreement means one of them misread the
    // lead, and we are not betting the owner's phone on which.
    if (hasScore && summary) {
      const clamped = Math.max(0, Math.min(100, Math.round(n)));
      if (Math.abs(clamped - fb.score) <= 25) {
        score = clamped;
        source = 'ai';
      } else {
        score = Math.round((clamped + fb.score) / 2);
        source = 'ai+rules(disagreed)';
        problems.push(`model score ${clamped} vs rules ${fb.score} — averaged`);
      }
    }
  }

  if (!summary) {
    const bits = [
      lead.service || 'enquiry',
      lead.message ? clip(lead.message, 90) : null,
      lead.city || null,
    ].filter(Boolean);
    summary = clip(bits.join(' \u2014 '), 200);
  }

  return {
    score,
    tier: tierFor(score),            // never trust a model-supplied tier
    summary,
    intent,
    urgency,
    next_question,
    red_flags,
    source,                          // 'ai' | 'ai+rules(disagreed)' | 'fallback'
    rule_score: fb.score,
    rule_reasons: fb.reasons,
    problems,                        // empty means the AI path ran clean
  };
}

// ---- n8n glue ----
// Reach back to node 1 for the lead, because the HTTP node replaced the item.
const norm = $('1. Normalize + validate').all();
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const lead = norm[Math.min(i, norm.length - 1)].json.lead;
  const resp = items[i].json ?? {};

  let text = '';
  let apiError = null;

  if (Array.isArray(resp.content)) {
    // Anthropic success. The assistant turn was prefilled with "{", so the
    // text that comes back is missing its opening brace — extractJson knows.
    text = resp.content.map((c) => c.text ?? '').join('');
  } else if (resp.error) {
    apiError = resp.error.message ?? JSON.stringify(resp.error);
  } else if (resp.message) {
    apiError = String(resp.message);
  } else {
    apiError = 'no response body from the model endpoint';
  }

  out.push({ json: { lead, q: qualify(lead, text, apiError) } });
}
return out;

// Node 3 of 3 — Compose the owner alert, the CRM record, and the audit row.
//
// The alert is written for a lock screen, not an inbox. The first line has to
// survive being truncated to ~55 characters by the notification, so the tier,
// the score and the name go first and nothing else competes for that space.
// The phone number is left bare on its own line so the OS linkifies it and the
// owner can dial by tapping once.

const SMS_SEGMENT = 160;
const MAX_SEGMENTS = 2;           // 320 chars. Past this, carriers split and bill extra.

function humanMs(ms) {
  if (!Number.isFinite(ms) || ms < 0) return 'n/a';
  if (ms < 1000) return `${Math.round(ms)}ms`;
  return `${(ms / 1000).toFixed(1)}s`;
}

function segments(text) {
  return Math.max(1, Math.ceil(String(text).length / SMS_SEGMENT));
}

function composeAlert(lead, q) {
  const head = `${q.tier}-LEAD ${q.score} ${lead.name || 'No name given'}`;

  const lines = [head];
  if (q.summary) lines.push(q.summary);
  if (lead.phone) lines.push(lead.phone);

  const meta = [lead.service, lead.city, lead.source].filter(Boolean).join(' | ');
  if (meta) lines.push(meta);

  if (q.next_question) lines.push(`Ask: ${q.next_question}`);
  if (q.red_flags?.length) lines.push(`Flag: ${q.red_flags.join('; ')}`);
  if (q.source !== 'ai') lines.push(`[scored by ${q.source}]`);

  let text = lines.join('\n');

  // Trim from the least important line up until it fits two segments. Never
  // truncate the head or the phone number — those are the whole point.
  const protectedCount = lead.phone ? 3 : 2;
  while (segments(text) > MAX_SEGMENTS && lines.length > protectedCount) {
    lines.splice(protectedCount, 1);
    text = lines.join('\n');
  }
  if (segments(text) > MAX_SEGMENTS) {
    text = text.slice(0, SMS_SEGMENT * MAX_SEGMENTS - 1) + '\u2026';
  }

  return text;
}

// WhatsApp is not SMS wearing a different logo. A Cloud API text message holds
// 4096 characters, so the context that composeAlert is forced to throw away to
// fit two segments can stay. That is the entire reason this is a separate
// function rather than a flag on the one above: the SMS alert is shaped by a
// billing limit, and repeating that limit where it does not apply would be
// cargo cult.
const WA_MAX = 4096;

function composeWhatsapp(lead, q) {
  const lines = [`*${q.tier}-LEAD ${q.score}* — ${lead.name || 'No name given'}`];
  if (q.summary) lines.push('', q.summary);

  const facts = [
    lead.phone && `Phone: ${lead.phone}`,
    lead.email && `Email: ${lead.email}`,
    lead.service && `Service: ${lead.service}`,
    lead.city && `Area: ${lead.city}`,
    `Source: ${lead.source}`,
  ].filter(Boolean);
  lines.push('', ...facts);

  // These three are the first casualties in the SMS. Here they survive, which
  // is the whole point of having the channel.
  if (q.intent) lines.push('', `Intent: ${q.intent}`);
  if (q.urgency) lines.push(`Urgency: ${q.urgency}`);
  if (q.next_question) lines.push('', `*Ask first:* ${q.next_question}`);
  if (q.red_flags?.length) lines.push('', `*Flags:* ${q.red_flags.join('; ')}`);
  if (q.source !== 'ai') lines.push('', `_[scored by ${q.source}]_`);

  const text = lines.join('\n');
  return text.length <= WA_MAX ? text : text.slice(0, WA_MAX - 1) + '\u2026';
}

// Meta Cloud API free-form text. Note this only delivers inside the 24-hour
// customer service window; outside it Meta requires an approved template, which
// is a provisioning decision and not something code can paper over.
function composeWhatsappPayload(lead, q, to) {
  return {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: String(to || '').replace(/^\+/, ''),   // Cloud API wants digits, no plus
    type: 'text',
    text: { preview_url: false, body: composeWhatsapp(lead, q) },
  };
}

function composeCrm(lead, q, locationId) {
  const parts = (lead.name || '').split(/\s+/).filter(Boolean);
  return {
    locationId: locationId || '',
    firstName: parts[0] || '',
    lastName: parts.slice(1).join(' '),
    name: lead.name || '',
    email: lead.email || undefined,
    phone: lead.phone || undefined,
    source: lead.source,
    tags: [
      'ai-qualified',
      `tier-${q.tier.toLowerCase()}`,
      lead.source,
      q.source === 'ai' ? 'scored-ai' : 'scored-rules',
    ].filter(Boolean),
    customFields: [
      { key: 'lead_score', field_value: String(q.score) },
      { key: 'lead_summary', field_value: q.summary },
      { key: 'lead_intent', field_value: q.intent || '' },
      { key: 'lead_urgency', field_value: q.urgency || '' },
    ],
  };
}

function compose(lead, q, opts = {}) {
  const now = opts.now ?? Date.now();
  const latency_ms = Number.isFinite(lead.t0) ? now - lead.t0 : null;
  const alert = composeAlert(lead, q);

  return {
    tier: q.tier,
    score: q.score,
    // Only an A pages the owner immediately. B and C land in the CRM and the
    // daily digest, which is the difference between a useful alert and one the
    // owner learns to ignore.
    notify_now: q.tier === 'A',
    alert_text: alert,
    alert_segments: segments(alert),
    whatsapp: composeWhatsappPayload(lead, q, opts.ownerPhone),
    crm: composeCrm(lead, q, opts.locationId),
    audit: {
      received_at: lead.received_at,
      name: lead.name,
      phone: lead.phone,
      email: lead.email,
      source: lead.source,
      service: lead.service,
      score: q.score,
      tier: q.tier,
      scored_by: q.source,
      rule_score: q.rule_score,
      problems: (q.problems || []).join('; '),
      latency_ms,
      latency_human: humanMs(latency_ms),
      dedupe_key: lead.dedupe_key,
    },
  };
}

// ---- n8n glue ----
const out = [];
for (const item of $input.all()) {
  const lead = item.json.lead;
  const q = item.json.q;
  out.push({ json: { lead, q, ...compose(lead, q, { locationId: $env.GHL_LOCATION_ID, ownerPhone: $env.OWNER_PHONE }) } });
}
return out;

// One row per lead, including how long the whole thing took and whether the
// AI or the rule engine produced the score. Swap this for a Google Sheets
// "Append Row" node and map these keys straight across.
return $input.all().map((i) => ({ json: i.json.audit }));

// Nothing is thrown away silently. An unreachable submission still gets a
// row, so "we never heard from them" can be told apart from "we dropped it".
const out = [];
for (const item of $input.all()) {
  out.push({ json: {
    outcome: 'not_contactable',
    reason: (item.json.errors || []).join('; '),
    warnings: (item.json.warnings || []).join('; '),
    lead: item.json.lead,
  } });
}
return out;
